from lib import *
S = SS('q35')
steps = [
    step("双写问题:先写数据库、再发消息,中间进程崩溃(用随机失败模拟,5% 的订单在提交之后、发消息之前“崩溃”)。1000 个订单:数据库里订单 1000 条,队列里的消息只有 942 条,丢了 58 条(正好是崩溃 58 次)——这些订单下游永远不知道。反过来先发消息再写库,崩溃会得到“有消息、没订单”的幽灵事件。两种顺序都不对,因为数据库和消息队列不在同一个事务里。", t=tl(S(1)), mark=lidx(S(1), '丢了 58 条消息'), done=lidx(S(1), '反过来'), b=bars([['数据库订单', 1000, '1000'], ['队列里的消息', 942, '942']], 1000, mark=[1], done=[0]), kv=KV([['先写库后发消息', '崩溃 → 丢消息(58/1000)'], ['先发消息后写库', '崩溃 → 幽灵事件'], ['根因', '库和队列不在同一事务']], ['根因'])),
    step("Outbox 模式:订单和“待发送事件”在同一个数据库事务里写入(要么都成功,要么都失败);另一个 relay 进程轮询 outbox 表,发消息、等 confirm、再标记已发送。同样的 1000 个订单,relay 在 5% 的发送后“崩溃”(消息已确认发出、还没标记):relay 崩溃 60 次、跑了 62 轮,队列里 1060 条消息——不同的订单事件正好 1000 个(没丢),重复 60 条(崩溃那一刻已发出的,重启后又发了一次)。outbox 把“可能丢”换成了“可能重复”,是至少一次;下游要去重。", t=tl(S(2)), mark=lidx(S(2), '重复 60 条', '队列里消息 1060 条'), done=lidx(S(2), 'relay 一共崩溃'), b=bars([['订单', 1000, '1000'], ['队列里的消息', 1060, '1060'], ['不同的事件', 1000, '1000'], ['重复', 60, '60']], 1060, mark=[3], done=[0, 1, 2]), kv=KV([['丢失', '0'], ['重复', '60(= relay 崩溃次数)'], ['语义', '至少一次']], ['语义'])),
    step("下游用去重把重复挡住:同样的消息流,消费者记下已处理的事件,业务效果只执行 1000 次——不同的事件 1000 个、业务效果 1000 次、订单 1000 个,一一对应。Outbox 负责“不丢”,消费端幂等(第 25 篇)负责“不重”,合起来才是端到端的效果恰好一次。", t=tl(S(3)), mark=lidx(S(3), '业务效果执行 1000 次'), done=lidx(S(3), '业务效果执行 1000 次'), kv=KV([['Outbox', '保证不丢'], ['消费端幂等', '保证不重复生效'], ['合起来', '端到端的效果恰好一次']], ['合起来'])),
    step("relay 的延迟:100 个订单每 20 ms 提交一个,relay 每隔 poll 间隔轮询一次,从订单提交到消息发布完成的延迟:poll 10 ms 时 p50 8 ms、p99 15 ms;poll 100 ms 时 p50 58 ms、p99 111 ms;poll 500 ms 时 p50 284 ms、p99 515 ms。延迟约等于半个 poll 间隔(p50)到一个 poll 间隔(p99);轮询越勤延迟越低,也越多查询数据库。", t=tl(S(4)), mark=lidx(S(4), 'poll 500 ms', 'poll 100 ms'), done=lidx(S(4), 'poll  10 ms'), b=bars([['poll 10 ms p50', 8, '8 ms'], ['poll 100 ms p50', 58, '58 ms'], ['poll 500 ms p50', 284, '284 ms'], ['poll 500 ms p99', 515, '515 ms']], 515, mark=[2, 3], done=[0, 1]), kv=KV([['延迟 p50', '≈ 半个 poll 间隔'], ['延迟 p99', '≈ 一个 poll 间隔'], ['代价', '轮询越勤,数据库查询越多']], ['延迟 p50'])),
    step("relay 的吞吐:单线程 relay 逐条带 confirm 发布 10000 行 outbox,区别只在“每批多少行提交一次 sent 标记”(数据库提交次数):每批 1 行,3506 ms(2852 行/秒);每批 100 行,1828 ms(5471 行/秒);每批 1000 行,1861 ms(5374 行/秒)。批量标记把数据库提交次数摊薄后快了近一倍,再大就没有收益,瓶颈转到逐条等 confirm 上。", t=tl(S(5)), mark=lidx(S(5), '每批    1', '每批  100'), done=lidx(S(5), '每批 1000'), b=bars([['每批 1', 2852, '2852 行/秒'], ['每批 100', 5471, '5471 行/秒'], ['每批 1000', 5374, '5374 行/秒']], 5471, mark=[0], done=[1, 2]), kv=KV([['每批 1 行', '2852 行/秒'], ['每批 100 行', '5471 行/秒'], ['再大', '瓶颈转到逐条 confirm']], ['每批 100 行'])),
]
A = mkartq('q35', 35, 'RabbitMQ,Outbox,事务,双写,最终一致,真实验证,动画演示',
    '用 sqlite + RabbitMQ 4.3.6 复现并解决双写问题:先写库再发消息会丢消息(1000 单丢 58 条);Outbox 模式(订单与待发送事件同事务,relay 轮询发布)不丢但重复 60 条,至少一次;配合下游去重业务只执行 1000 次;relay 延迟约等于 poll 间隔,批量标记把吞吐从 2852 提到 5471 行/秒。',
    '“先改数据库、再发消息”看似简单,进程在两步之间崩溃就会让数据库和下游不一致。Outbox 模式是业界标准解法。它到底解决什么、引入什么新问题、relay 的延迟和吞吐是多少?这篇用真实的数据库和 RabbitMQ 复现。',
    [('58 / 1000', '先写库再发消息、5% 崩溃时,丢失的消息条数'), ('0 丢 / 60 重复', 'Outbox + relay 崩溃 60 次后,订单事件的丢失与重复条数'), ('8 / 58 / 284 ms', 'poll 间隔 10 / 100 / 500 ms 时的 relay 延迟 p50')],
    [('双写问题', '<p>写数据库和发消息不在同一个事务里,两步之间崩溃就会不一致:实测先写库后发消息会丢消息。</p>'),
     ('Outbox', '<p>把“待发送事件”和业务数据放进同一个数据库事务,由 relay 单独轮询发送、确认后标记。这样不会丢,但 relay 在“已发送、未标记”时崩溃会重复发送,所以是至少一次(见下)。</p>'),
     ('Outbox 的新问题', '<p>relay 在“消息已确认、标记未写”时崩溃,重启后会再发一次:实测 relay 崩溃 60 次,队列里多出 60 条重复。</p>'),
     ('配合幂等', '<p>下游用事件 id 去重,Outbox 的“不丢”加上消费端的“不重”,就得到端到端的效果恰好一次。</p>'),
     ('延迟与吞吐', '<p>relay 延迟取决于轮询间隔(p50 约半个间隔);批量标记 sent 能减少数据库提交次数,吞吐提高近一倍。</p>')],
    steps,
    [ENV_Q + '。数据库是 sqlite(WAL);崩溃用随机数模拟(固定随机种子);relay 逐条等待 confirm 并只在确认后标记 sent;延迟取每个订单从提交到发布完成,100 个订单取 p50 / p99;吞吐是 10000 行 outbox 的整体耗时,单次测量',
     '没有验证:真实进程被 kill -9 时的行为(这里是在代码里模拟崩溃);多个 relay 实例并发(需要行锁 / SKIP LOCKED);基于数据库日志(CDC)的 outbox;outbox 表的清理策略与增长;事务性发件箱在 PostgreSQL / MySQL 上的实现细节;消息顺序(同一聚合按 id 顺序发,这里没有专门验证)'],
    'Outbox 模式')
